messages.content:
Write the application service of PayOrder.

Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "Order",
   "table": "payment_orders",
   "legacy_table": "ORDENES",
   "key": [
    "orderNumber",
    "companyNumber"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ORD_NUMERO"
    },
    {
     "name": "companyNumber",
     "type": "integer(32,signed)",
     "column": "company_number",
     "legacy": "ORD_EMPRESA"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ORD_ESTADO"
    },
    {
     "name": "orderValue",
     "type": "decimal(11,2,signed)",
     "column": "order_value",
     "legacy": "ORD_VALOR"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": "movement_number",
     "legacy": "ORD_MOVIM"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": "commission",
     "legacy": "ORD_COMIS"
    }
   ]
  },
  {
   "name": "Account",
   "table": "customer_accounts",
   "legacy_table": "CUENTAS",
   "key": [
    "accountNumber"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": "account_number",
     "legacy": "CTA_NUMERO"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "CTA_TIPO"
    },
    {
     "name": "balance",
     "type": "decimal(13,2,signed)",
     "column": "balance",
     "legacy": "CTA_SALDO"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "CTA_ESTADO"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "OrderRepository",
   "entity": "Order",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByKeyForUpdate",
     "description": "Reads the order by order number and company, locking the row (READ FILE ORDENES UPDATE). Empty when it does not exist (NOTFND).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      }
     ],
     "returns": "Order",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Sets the order to paid ('G') and stores the movement number and the commission charged (REWRITE FILE ORDENES).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      },
      {
       "name": "movementNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "ORD_MOVIM"
      },
      {
       "name": "commission",
       "type": "decimal(5,2,signed)",
       "column": null,
       "legacy": "ORD_COMIS"
      }
     ],
     "returns": null,
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberForUpdate",
     "description": "Reads the account by number, locking the row (READ FILE CUENTAS UPDATE). Empty when it does not exist (NOTFND).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    },
    {
     "name": "updateBalance",
     "description": "Writes the new balance of the account (REWRITE FILE CUENTAS).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      },
      {
       "name": "balance",
       "type": "decimal(13,2,signed)",
       "column": null,
       "legacy": "CTA_SALDO"
      }
     ],
     "returns": null,
     "legacy_output": null
    }
   ]
  },
  {
   "name": "MovementGateway",
   "entity": null,
   "legacy_program": "PAGOMOV",
   "methods": [
    {
     "name": "registerMovement",
     "description": "Registers the payment movement for the order and returns the movement number.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "MOV_ORDEN"
      }
     ],
     "returns": "long",
     "legacy_output": "MOV_NUMERO"
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "DebitAccount",
   "description": "Debits an amount from a customer account after checking that it exists, that the type matches, that it is active and that the balance is sufficient (a balance equal to the amount is allowed). Called by PayOrder inside its transaction and also exposed on its own.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005"
   ],
   "inputs": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "CUENTA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "TIPCTA"
    },
    {
     "name": "amount",
     "type": "decimal(13,2,signed)",
     "column": null,
     "legacy": "VALOR"
    }
   ],
   "outputs": [
    {
     "name": "balance",
     "type": "decimal(13,2,signed)",
     "column": null,
     "legacy": "CTA_SALDO"
    },
    {
     "name": "responseCode",
     "type": "text(fixed,2,iso8859-1)",
     "column": null,
     "legacy": "MENSAJE"
    }
   ],
   "errors": [
    {
     "code": "ACCOUNT_NOT_FOUND",
     "legacy_code": "30",
     "message": "CUENTA NO VALIDA"
    },
    {
     "code": "ACCOUNT_TYPE_MISMATCH",
     "legacy_code": "40",
     "message": "CUENTA NO VALIDA"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "10",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "20",
     "message": "SALDO INSUFICIENTE"
    }
   ],
   "ports": [
    "AccountRepository"
   ],
   "http_method": "POST",
   "path": "/accounts/debit",
   "legacy_program": "PAGODEB",
   "unit_of_work": null,
   "legacy_message": "MENSAJE"
  },
  {
   "name": "PayOrder",
   "description": "Pays a pending order: validates the request (order number, account type, channel, approval key), reads the order, checks it is pending and that the amount equals the order value, calculates the commission, debits the account through DebitAccount, registers the movement and marks the order as paid, all in one transaction.",
   "rules": [
    "RULE-007",
    "RULE-008",
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013",
    "RULE-014",
    "RULE-015"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "ORDEN"
    },
    {
     "name": "companyNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "EMPRESA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "TIPCTA"
    },
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "CUENTA"
    },
    {
     "name": "amount",
     "type": "decimal(11,2,signed)",
     "column": null,
     "legacy": "VALOR"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "CANAL"
    },
    {
     "name": "approvalKey",
     "type": "text(fixed,6,iso8859-1)",
     "column": null,
     "legacy": "CLAVE"
    }
   ],
   "outputs": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "RORDEN"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": null,
     "legacy": "RCOMIS"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "RMOVIM"
    },
    {
     "name": "resultMessage",
     "type": "text(var,40,iso8859-1)",
     "column": null,
     "legacy": "RMENS"
    },
    {
     "name": "message",
     "type": "text(var,78,iso8859-1)",
     "column": null,
     "legacy": "MENSAJE"
    }
   ],
   "errors": [
    {
     "code": "INVALID_ORDER_NUMBER",
     "legacy_code": "HAY-ERROR",
     "message": "NUMERO DE ORDEN INVALIDO"
    },
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "HAY-ERROR",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "CHANNEL_NOT_ALLOWED",
     "legacy_code": "HAY-ERROR",
     "message": "CANAL NO PERMITIDO"
    },
    {
     "code": "APPROVAL_KEY_REQUIRED",
     "legacy_code": "HAY-ERROR",
     "message": "CLAVE DE APROBACION REQUERIDA"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "HAY-ERROR",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "HAY-ERROR",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "AMOUNT_MISMATCH",
     "legacy_code": "HAY-ERROR",
     "message": "VALOR NO COINCIDE CON LA ORDEN"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "10",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "20",
     "message": "SALDO INSUFICIENTE"
    },
    {
     "code": "ACCOUNT_INVALID",
     "legacy_code": "OTHER",
     "message": "CUENTA NO VALIDA"
    }
   ],
   "ports": [
    "OrderRepository",
    "AccountRepository",
    "MovementGateway"
   ],
   "http_method": "POST",
   "path": "/orders/payments",
   "legacy_program": "PAGOORD",
   "unit_of_work": {
    "begins_at": 37,
    "commits_at": 172,
    "savepoints": [],
    "rollbacks": []
   },
   "legacy_message": "MENSAJE"
  },
  {
   "name": "NavigateMenu",
   "description": "Routes the option chosen on the payments main menu: '1' goes to order payment, '9' ends the session, any other option is rejected with 'OPCION NO VALIDA'.",
   "rules": [
    "RULE-006"
   ],
   "inputs": [
    {
     "name": "option",
     "type": "text(fixed,1,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    }
   ],
   "outputs": [
    {
     "name": "destination",
     "type": "text(var,8,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    },
    {
     "name": "message",
     "type": "text(fixed,78,iso8859-1)",
     "column": null,
     "legacy": "MENSAJEO"
    }
   ],
   "errors": [
    {
     "code": "INVALID_OPTION",
     "legacy_code": "OTHER",
     "message": "OPCION NO VALIDA"
    }
   ],
   "ports": [],
   "http_method": "POST",
   "path": "/menu/options",
   "legacy_program": "PAGOMNU",
   "unit_of_work": null,
   "legacy_message": "MENSAJEO"
  }
 ],
 "decisions": [
  {
   "title": "Transaction boundary replaces the CICS syncpoint",
   "context": "PAGOORD works in one unit of work that ends with EXEC CICS SYNCPOINT (line 172). The debit made by PAGODEB (LINK), the PAGOMOV call and the order rewrite are all in that unit. The legacy has no explicit rollback or savepoint.",
   "decision": "PayOrder runs in a single database transaction from line 37 to line 172. DebitAccount is called in-process, so the debit, the movement registration and the order update commit or roll back together. There are no savepoints, so no UnitOfWork port is declared. Every rejection raises a business exception before any write, and an unexpected failure rolls back the whole transaction.",
   "consequences": "A failure after the debit, for example in PAGOMOV, now also undoes the debit. The legacy only had that guarantee through CICS syncpoint rollback on abend."
  },
  {
   "title": "VSAM files move to relational tables",
   "context": "ORDENES and CUENTAS are VSAM KSDS files read with UPDATE and rewritten.",
   "decision": "data_strategy is migration. ORDENES becomes payment_orders and CUENTAS becomes customer_accounts, keeping the legacy precision. READ ... UPDATE becomes a pessimistic row lock (SELECT ... FOR UPDATE) in the findByKeyForUpdate and findByNumberForUpdate methods.",
   "consequences": "The data must be loaded before cut-over. Locking behaviour is equivalent but is now enforced by the database."
  },
  {
   "title": "Amount is received as a decimal",
   "context": "The screen field VALORI is a text field and the legacy computes NUMVAL(VALORI)/100 (implied two decimals, picture 9(9)V99). The recorded traces already provide the value as a decimal such as 1500.00.",
   "decision": "The service takes the amount as decimal(11,2,signed) and compares it with the order value for equality. The conversion from the 11-character screen format belongs to the input adapter. Order number, account type, channel and key stay as text so that the 'not numeric' and 'blank key' checks keep working.",
   "consequences": "Clients must send an already-scaled amount, not the 11-digit screen string."
  },
  {
   "title": "Debit logic lives in its own use case",
   "context": "PAGODEB is a program called with LINK. Its rules (RULE-001 to RULE-005) are the same ones PAGOORD depends on, and its return codes are translated by PAGOORD (RULE-014). Its commarea fields are traced through the matching screen fields and table columns of PAGOORD (account, type, amount, balance).",
   "decision": "DebitAccount implements PAGODEB and is also exposed on its own at POST /accounts/debit. PayOrder calls it in-process and maps its rejections: '10' becomes ACCOUNT_INACTIVE, '20' becomes INSUFFICIENT_FUNDS, and '30' and '40' become ACCOUNT_INVALID.",
   "consequences": "The rules are not duplicated. The rejection response code ('00', '10', '20', '30', '40') becomes a business error code."
  },
  {
   "title": "PAGOMOV is an external program behind a port",
   "context": "PAGOMOV is not among the inputs (it is a stub) and only its call contract is known: it receives MOV_ORDEN and returns MOV_NUMERO.",
   "decision": "MovementGateway represents it and is replaced by the recorded stubs when the golden master is replayed.",
   "consequences": "The real movement logic must be provided or migrated separately."
  },
  {
   "title": "Screens, pseudo-conversational flow and commarea are not translated",
   "context": "The legacy uses BMS maps, PF keys (PF3, 'TECLA NO VALIDA'), XCTL and a 13-byte commarea to keep state between interactions (including the last paid order).",
   "decision": "They are replaced by REST endpoints. The menu routing (RULE-006) is returned by NavigateMenu as a destination plus a message, and the commarea is not an input or output of the service. The last paid order is already returned as orderNumber in the payment result, so the client keeps it as its own state.",
   "consequences": "PF-key handling, screen redisplay and the commarea disappear. Navigation to PAGOORD and the end of the session are decided by the client from the destination."
  }
 ],
 "masks": [],
 "infrastructure": [],
 "data_strategy": "migration"
}

Rules:
[
 {
  "id": "RULE-007",
  "name": "Order number must be numeric and non-zero",
  "category": "validation",
  "priority": "P1",
  "statement": "When the order number ORDENI is not numeric or equals zeros, the message 'NUMERO DE ORDEN INVALIDO' is set in WS-MENSAJE and the HAY-ERROR flag is set.",
  "condition": "ORDENI NOT NUMERIC OR ORDENI = ZEROS",
  "action": "Set message 'NUMERO DE ORDEN INVALIDO' and flag the request as in error. No order is read and no debit is made.",
  "inputs": [
   {
    "name": "ORDENI",
    "type": "text(fixed,7,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order number is zero\n Given the order number entered is 0000000\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown and the payment is not processed",
   "Scenario: Order number contains letters\n Given the order number entered is 12A4567\n When the user presses ENTER\n Then the message 'NUMERO DE ORDEN INVALIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 83,
    "line_end": 85
   }
  ]
 },
 {
  "id": "RULE-008",
  "name": "Allowed account types for order payment",
  "category": "validation",
  "priority": "P0",
  "statement": "Only account types CTE, AHO and VIR may be used to pay an order. Any other type is rejected with 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "TIPCTAI NOT IN ('CTE','AHO','VIR')",
  "action": "Set message 'TIPO DE CUENTA NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "TIPCTAI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Savings account accepted\n Given a valid order number and account type AHO\n When the request is validated\n Then the account type check passes",
   "Scenario: Unknown account type\n Given a valid order number and account type XYZ\n When the request is validated\n Then the message 'TIPO DE CUENTA NO PERMITIDO' is shown"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 87,
    "line_end": 90
   }
  ]
 },
 {
  "id": "RULE-009",
  "name": "Allowed channels for order payment",
  "category": "validation",
  "priority": "P1",
  "statement": "The payment channel must be WEB or OFI. Any other channel is rejected with 'CANAL NO PERMITIDO'.",
  "condition": "CANALI NOT IN ('WEB','OFI')",
  "action": "Set message 'CANAL NO PERMITIDO' and flag the request as in error.",
  "inputs": [
   {
    "name": "CANALI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Invalid channel\n Given a valid order number, account type CTE and channel ATM\n When the request is validated\n Then the message 'CANAL NO PERMITIDO' is shown",
   "Scenario: Valid channel\n Given channel WEB\n When the request is validated\n Then the channel check passes"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 92,
    "line_end": 94
   }
  ]
 },
 {
  "id": "RULE-010",
  "name": "Office channel requires approval key",
  "category": "validation",
  "priority": "P1",
  "statement": "A payment through the office channel (OFI) must carry an approval key. If the key is blank the request is rejected with 'CLAVE DE APROBACION REQUERIDA'.",
  "condition": "CANALI = 'OFI' AND CLAVEI = SPACES",
  "action": "Set message 'CLAVE DE APROBACION REQUERIDA' and flag the request as in error.",
  "inputs": [
   {
    "name": "CANALI",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   },
   {
    "name": "CLAVEI",
    "type": "text(fixed,6,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: OFI without key\n Given channel OFI and a blank approval key\n When the request is validated\n Then the message 'CLAVE DE APROBACION REQUERIDA' is shown",
   "Scenario: WEB without key\n Given channel WEB and a blank approval key\n When the request is validated\n Then no error is raised for the key"
  ],
  "sources": [
   {
    "file": "cbl/PAGOORD.cbl",
    "line_start": 96,
    "line_end": 99
   }
  ]
 },
 {
  "id": "RULE-011",
  "name": "Order must exist and be pending",
  "category": "validation",
  "priority": "P0",
  "statement": "The order, identified by company and order number, must exist and be in pending status to be paid. Otherwise the payment is rejected with 'ORDEN NO EXISTE' or 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "READ of ORDENES by (EMPRESAI, ORDENI) returns NOTFND, or the record is not ORD-PENDIENTE",
  "action": "Set 'ORDEN NO EXISTE' if not found, or 'ORDEN NO ESTA PENDIENTE' if the status is not pending, and flag the request as in error.",
  "inputs": [
   {
    "name": "ORDENI",
    "type": "text(fixed,7,ebcdic)",
    "description": ""
   },
   {
    "name": "EMPRESAI",
    "type": "text(fixed,5,ebcdic)",
    "description": ""
   },
   {
    "name": "ORD-ESTADO",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "WS-MENSAJE",
    "type": "text(fixed,78,ebcdic)",
    "description": ""
   },
   {
    "name": "WS-ERROR",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order not found\n Given no order 1234567 exists for company 00010\n When payment is requested\n Then the message 'ORDEN NO EXISTE' is shown",
   "Scenario: Order already paid\n Given order 1234567 exists with a status other than pending\n When payment is requested\n Then the message 'ORDEN NO ESTA PENDIENTE' is shown"
  ],
  "sources": [
   {
