package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.Order;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Optional;

/** Use case PayOrder (legacy PAGOORD, with the debit logic of PAGODEB executed in-process). */
public class PayOrderService {

    private static final String HAY_ERROR = "HAY-ERROR";
    private static final String PENDING_STATUS = "P";
    private static final String ACTIVE_STATUS = "A";
    private static final BigDecimal COMMISSION_THRESHOLD = new BigDecimal("50000");

    private final OrderRepository orderRepository;
    private final AccountRepository accountRepository;
    private final MovementGateway movementGateway;

    public PayOrderService(OrderRepository orderRepository,
                           AccountRepository accountRepository,
                           MovementGateway movementGateway) {
        this.orderRepository = orderRepository;
        this.accountRepository = accountRepository;
        this.movementGateway = movementGateway;
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        // 2100-VALIDAR-ENTRADA (nested IF: first failing check wins)
        String orderNumberText = fixed(request.orderNumber(), 7);
        String accountType = fixed(request.accountType(), 3);
        String channel = fixed(request.channel(), 3);
        String approvalKey = fixed(request.approvalKey(), 6);

        if (!isNumeric(orderNumberText) || isAllZeros(orderNumberText)) {
            throw new BusinessError("INVALID_ORDER_NUMBER", HAY_ERROR, "NUMERO DE ORDEN INVALIDO");
        }
        if (!accountType.equals("CTE") && !accountType.equals("AHO") && !accountType.equals("VIR")) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", HAY_ERROR, "TIPO DE CUENTA NO PERMITIDO");
        }
        if (!channel.equals("WEB") && !channel.equals("OFI")) {
            throw new BusinessError("CHANNEL_NOT_ALLOWED", HAY_ERROR, "CANAL NO PERMITIDO");
        }
        if (channel.equals("OFI") && approvalKey.isBlank()) {
            throw new BusinessError("APPROVAL_KEY_REQUIRED", HAY_ERROR, "CLAVE DE APROBACION REQUERIDA");
        }

        // 2200-LEER-ORDEN
        Integer orderNumber = Integer.valueOf(orderNumberText);
        Integer companyNumber = request.companyNumber();
        Optional<Order> found = orderRepository.findByKeyForUpdate(orderNumber, companyNumber);
        if (found.isEmpty()) {
            throw new BusinessError("ORDER_NOT_FOUND", HAY_ERROR, "ORDEN NO EXISTE");
        }
        Order order = found.get();
        if (!PENDING_STATUS.equals(fixed(order.status(), 1))) {
            throw new BusinessError("ORDER_NOT_PENDING", HAY_ERROR, "ORDEN NO ESTA PENDIENTE");
        }
        BigDecimal amount = request.amount() == null ? BigDecimal.ZERO : request.amount();
        BigDecimal wsValor = amount.setScale(2, RoundingMode.DOWN);
        if (wsValor.compareTo(order.orderValue()) != 0) {
            throw new BusinessError("AMOUNT_MISMATCH", HAY_ERROR, "VALOR NO COINCIDE CON LA ORDEN");
        }

        // 2300-CALCULAR-COMISION
        BigDecimal commission;
        if (order.orderValue().compareTo(COMMISSION_THRESHOLD) >= 0) {
            commission = new BigDecimal("0.00");
        } else if (channel.equals("WEB")) {
            commission = new BigDecimal("1.00");
        } else {
            commission = new BigDecimal("2.50");
        }
        BigDecimal total = order.orderValue().add(commission);

        // 2400-DEBITAR-CUENTA (PAGODEB logic)
        debit(request.accountNumber(), accountType, total);

        // 2500-REGISTRAR-PAGO
        long movementNumber = movementGateway.registerMovement(order.orderNumber());
        orderRepository.markPaid(orderNumber, companyNumber, movementNumber, commission);

        // 2600-ENVIAR-RESULTADO
        return new PayOrderResponse(order.orderNumber(), commission, movementNumber, "PAGO REALIZADO", null);
    }

    /** PAGODEB: read account, evaluate in order, subtract and rewrite. */
    private void debit(Long accountNumber, String accountType, BigDecimal total) {
        Optional<Account> found = accountRepository.findByNumberForUpdate(accountNumber);
        if (found.isEmpty()) {
            // '30'
            throw new BusinessError("ACCOUNT_INVALID", "OTHER", "CUENTA NO VALIDA");
        }
        Account account = found.get();
        if (!fixed(account.accountType(), 3).equals(accountType)) {
            // '40'
            throw new BusinessError("ACCOUNT_INVALID", "OTHER", "CUENTA NO VALIDA");
        }
        if (!ACTIVE_STATUS.equals(fixed(account.status(), 1))) {
            // '10'
            throw new BusinessError("ACCOUNT_INACTIVE", "10", "CUENTA INACTIVA");
        }
        if (account.balance().compareTo(total) < 0) {
            // '20'
            throw new BusinessError("INSUFFICIENT_FUNDS", "20", "SALDO INSUFICIENTE");
        }
        accountRepository.updateBalance(accountNumber, account.balance().subtract(total));
    }

    /** Emulates a fixed-length PIC X field: null as spaces, right-padded or truncated. */
    private static String fixed(String value, int length) {
        String v = value == null ? "" : value;
        if (v.length() >= length) {
            return v.substring(0, length);
        }
        StringBuilder sb = new StringBuilder(v);
        while (sb.length() < length) {
            sb.append(' ');
        }
        return sb.toString();
    }

    private static boolean isNumeric(String value) {
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static boolean isAllZeros(String value) {
        for (int i = 0; i < value.length(); i++) {
            if (value.charAt(i) != '0') {
                return false;
            }
        }
        return true;
    }
}
